const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const tz = 'Asia/Bangkok';
const today = DateTime.now().setZone(tz).startOf('day');
const d0 = today.minus({ days: 6 }).toISODate();   // this week = last 7 days incl today
const dPrev = today.minus({ days: 13 }).toISODate();
const todayStr = today.toISODate();

// Read Archive feeds Read Feedback feeds this node, so the archive rows come from the
// named node and $input is the job_feedback table. 'nudged' rows are follow-up markers,
// not statuses, and are excluded here.
const rows = $('Read Archive').all().map(i => i.json).filter(r => r && r.url);
const fb = $input.all().map(i => i.json).filter(r => r && r.archive_id !== undefined && r.archive_id !== null && r.rating !== 'nudged');
const day = (r) => String(r.first_seen || '').slice(0, 10);
const isSent = (r) => r.delivered === true || r.delivered === 1 || r.delivered === 'true';
const wk = rows.filter(r => day(r) >= d0 && day(r) <= todayStr);
const pv = rows.filter(r => day(r) >= dPrev && day(r) < d0);

const L = [];
L.push('📊 <b>Weekly job-hunt stats</b> — ' + d0 + ' to ' + todayStr);

if (wk.length === 0) {
  L.push('');
  L.push('No jobs scored this week. That usually means the agent did not run — worth checking n8n.');
  return [{ json: { text: L.join('\n') } }];
}

const sent = wk.filter(isSent);
const sentPv = pv.filter(isSent);
const delta = (a, b) => { const d = a - b; return b === 0 ? '' : (d > 0 ? ' (+' + d + ')' : (d < 0 ? ' (' + d + ')' : ' (=)')); };

L.push('');
L.push('<b>Funnel</b>');
L.push('• scored: ' + wk.length + delta(wk.length, pv.length));
L.push('• delivered: ' + sent.length + delta(sent.length, sentPv.length) + ' (' + Math.round(100 * sent.length / wk.length) + '% of scored)');
L.push('• days with a digest: ' + new Set(sent.map(day)).size + ' of 7');

// pipeline — what the user DID with what was delivered (job_feedback button presses).
// "this week" counts events; "all time" uses the LATEST status per job (append-only log,
// latest wins). applied/no_reply = still waiting; replied/rejected = closed.
if (fb.length) {
  const byJob = {};
  for (const e of fb) { const k = String(e.archive_id); if (!byJob[k] || String(e.rated_at) > String(byJob[k].rated_at)) byJob[k] = e; }
  const latest = Object.values(byJob);
  const wkEv = fb.filter(e => String(e.rated_at).slice(0, 10) >= d0);
  const cnt = (arr, st) => arr.filter(e => e.rating === st).length;
  const appliedAll = latest.filter(e => ['applied', 'no_reply', 'replied', 'rejected'].includes(e.rating));
  const replied = cnt(latest, 'replied'), rejected = cnt(latest, 'rejected');
  const waiting = latest.filter(e => e.rating === 'applied' || e.rating === 'no_reply');
  L.push('');
  L.push('<b>Pipeline</b> (from your buttons)');
  L.push('• this week: applied ' + cnt(wkEv, 'applied') + ' · saved ' + cnt(wkEv, 'saved') + ' · skipped ' + cnt(wkEv, 'skipped') + ' · replies ' + cnt(wkEv, 'replied') + ' · rejected ' + cnt(wkEv, 'rejected'));
  L.push('• all time: applied ' + appliedAll.length + ' → replies ' + replied + (appliedAll.length ? ' (' + Math.round(100 * replied / appliedAll.length) + '%)' : '') + ' · rejected ' + rejected + ' · saved ' + cnt(latest, 'saved'));
  if (waiting.length) {
    const oldest = Math.max(...waiting.map(e => Math.floor(today.diff(DateTime.fromISO(String(e.rated_at)).setZone(tz).startOf('day'), 'days').days)));
    L.push('• waiting on a reply: ' + waiting.length + ' (oldest ' + oldest + 'd)');
  }
}

// score spread — this is what tells you whether a model/prompt change moved calibration
const buckets = [[90, 100, '90+'], [80, 90, '80s'], [70, 80, '70s'], [60, 70, '60s'], [40, 60, '40-59'], [0, 40, 'under 40']];
L.push('');
L.push('<b>Score spread</b>');
for (const [lo, hi, lbl] of buckets) {
  const n = wk.filter(r => Number(r.score) >= lo && Number(r.score) < hi).length;
  if (n) L.push('• ' + lbl.padEnd(9) + ' ' + n);
}

// which sources earn their token spend
const agg = {};
for (const r of wk) {
  const a = agg[r.source] || (agg[r.source] = { n: 0, hit: 0, sent: 0 });
  a.n++;
  if (Number(r.score) >= 60) a.hit++;
  if (isSent(r)) a.sent++;
}
L.push('');
L.push('<b>Sources</b> (scored → hit-rate → sent)');
for (const [s, a] of Object.entries(agg).sort((x, y) => y[1].hit - x[1].hit)) {
  L.push('• ' + esc(s) + ': ' + a.n + ' → ' + Math.round(100 * a.hit / a.n) + '% → ' + a.sent);
}

const top = sent.slice().sort((a, b) => Number(b.score) - Number(a.score)).slice(0, 5);
if (top.length) {
  L.push('');
  L.push('<b>Best delivered this week</b>');
  for (const r of top) L.push('• ' + Number(r.score) + ' · <a href="' + esc(r.url) + '">' + esc(String(r.title).slice(0, 60)) + '</a>');
}

// near-misses: what the gate is rejecting. If these look good, the gate is too high.
const near = wk.filter(r => !isSent(r) && Number(r.score) >= 40).sort((a, b) => Number(b.score) - Number(a.score)).slice(0, 5);
if (near.length) {
  L.push('');
  L.push('<b>Near misses</b> (scored 40+, not sent)');
  for (const r of near) L.push('• ' + Number(r.score) + ' · ' + esc(String(r.title).slice(0, 55)) + ' — ' + esc(r.seniority_fit || ''));
}

let text = L.join('\n');
if (text.length > 3800) text = text.slice(0, 3780) + '\n…(truncated)';
return [{ json: { text } }];
